// src/hooks/useAttendanceData.js
import { useEffect, useState } from "react";

const useAttendanceData = (selectedDate) => {
  const [monthPieData, setMonthPieData] = useState([]);
  const [barChartData, setBarChartData] = useState([]);

  useEffect(() => {
    const month = selectedDate.getMonth() + 1;
    const allKeys = Object.keys(localStorage);
    const monthlyData = {};

    allKeys.forEach((key) => {
      if (!/^\d{4}-\d{2}-\d{2}$/.test(key)) return; // 날짜 키만 필터
      const date = new Date(key);
      if (date.getMonth() + 1 !== month) return;

      const records = JSON.parse(localStorage.getItem(key));
      records.forEach(({ project, time }) => {
        if (!monthlyData[project]) monthlyData[project] = 0;
        monthlyData[project] += time;
      });
    });

    const chartData = Object.entries(monthlyData).map(([name, value]) => ({
      name,
      value,
    }));

    setMonthPieData(chartData);
    setBarChartData(chartData);
  }, [selectedDate]);

  const getTopProjectSummary = () => {
    if (monthPieData.length === 0) return "이번 달 근무 데이터가 없습니다.";

    const total = monthPieData.reduce((sum, item) => sum + item.value, 0);
    const sorted = [...monthPieData].sort((a, b) => b.value - a.value);
    const topProject = sorted[0];
    const percentages = sorted.map(
      (proj) => `${proj.name} 프로젝트는 ${((proj.value / total) * 100).toFixed(1)}%`
    );

    return `${selectedDate.getMonth() + 1}월 달 가장 많은 기여를 한 프로젝트는 ${topProject.name}입니다. ${percentages.join(", ")}입니다.`;
  };

  return {
    pieChartData: monthPieData,
    barChartData,
    monthPieData,
    getTopProjectSummary,
  };
};

export default useAttendanceData;
